ecialchars(ucfirst($r['resolution_action'] ?? 'resolved')) ?></p><?php endif; ?></article><?php endforeach; ?></div>
</details><?php endforeach; ?></div></details><?php endforeach; endif; ?></section><?php endif; ?>
